insert into public.settings(key,value) values('telegram_editorial:club-lab-2026-10-26',$editorial${"posts":[{"key":"evidence-receipt","text":"🧾 <b>Счёт-фактура на каждый факт</b>\n\nОдна из полезных привычек при работе с ИИ: просить не «ещё раз всё проверить», а отдельную квитанцию на утверждения. Текст может выглядеть убедительно и всё равно опираться на пустоту.\n\nПопробуй на одном своём посте:\n\n<pre>Раздели текст на проверяемые утверждения. Для каждого верни: факт → доступное основание → место в источнике → статус «подтверждено / вывод / не найдено». Не ищи оправдание тезису: если опоры нет, предложи удалить или ослабить формулировку. Не создавай цитат. В конце собери версию текста только с подтверждёнными фактами и явно отмеченными выводами.</pre>\n\nПроверка на 3 минуты: выбери три строки таблицы и открой основания вручную. Если ссылка существует, но не подтверждает именно эту мысль, строка не прошла.\n\n#ТолькоВКанале #ПрактикаИИ"},{"key":"scene-experiment","text":"🎥 <b>Один продукт, три истории — без новой подписки</b>\n\nВозьми собственный предмет: кружку, упаковку, наушники. Вместо десяти похожих генераций сделай три разных задания:\n\n1. <b>Каталог:</b> форма и материал читаются без декора.\n2. <b>Ситуация:</b> понятно, когда предмет нужен человеку.\n3. <b>Деталь:</b> одна особенность занимает почти весь кадр.\n\n<pre>Предмет: [описание и собственное фото]. Создай три съёмочных задания: каталог, ситуация использования, деталь. В каждом укажи положение предмета, высоту камеры, направление света, фон, свободную область под подпись. Сохрани геометрию и текст на упаковке. Не меняй сам продукт, меняй рассказ о нём.</pre>\n\nСравни не «красоту вообще», а три вещи: узнаётся ли предмет, понятно ли сообщение, читается ли кадр на телефоне. Удачные задания сохрани вместе с референсом.\n\n#ТолькоВКанале #ВизуальнаяЛаборатория"},{"key":"bug-protocol","text":"🧯 <b>«Почини всё» заменяем на маленький протокол</b>\n\nКогда кодинг-агент чинит один баг и попутно переделывает половину проекта, проблема часто начинается с размытой границы задачи. Вот короткий рабочий контракт:\n\n<pre>Симптом: […]. Повторить: 1) […] 2) […]. Ожидание: […]. Сначала покажи минимальное воспроизведение и гипотезу причины. Измени только то, что необходимо для этого случая. После патча запусти ту же проверку и один соседний сценарий. В отчёте: причина, изменённые файлы, результаты, что осталось непроверенным. Рефакторинг не включай без отдельной причины.</pre>\n\nМаленький тест для самого задания: сможет ли другой человек повторить ошибку, не читая твои мысли? Если нет — сначала допиши шаги.\n\nЭто метод работы, а не обещание, что любой агент исправит любой проект с первой попытки.\n\n#ТолькоВКанале #Вайбкодинг"},{"key":"deal-radar","text":"📡 <b>Радар выгод · 26 октября 2026</b>\n\nЗдесь важно, <i>кому</i> доступно предложение. Не все акции подходят для Казахстана.\n\n• <a href=\"https://help.openai.com/en/articles/20001493-chatgpt-back-to-school-offer-for-students\">ChatGPT Plus</a>: четыре бесплатных месяца для подходящих студентов вузов США. Активация до 31 октября, нужна проверка и платёжный метод; затем платное продление.\n\n• <a href=\"https://docs.github.com/en/enterprise-cloud@latest/copilot/how-tos/copilot-on-github/set-up-copilot/enable-copilot/set-up-for-students\">GitHub Copilot Student</a>: бесплатный доступ после подтверждения GitHub Education; действуют лимиты аккаунта.\n\n• <a href=\"https://www.perplexity.ai/help-center/en/articles/12590157-what-is-education-pro\">Perplexity Education Pro</a>: студенческая/преподавательская скидка после проверки. Это не универсальный бесплатный год.\n\n• <a href=\"https://support.google.com/googleone/answer/17422238?hl=en\">Google AI для студентов</a>: условия зависят от предложения и страны. Не путай американский бесплатный trial со студенческим bundle в других странах.\n\n• <a href=\"https://huggingface.co/docs/hub/spaces-zerogpu\">Hugging Face ZeroGPU</a>: бесплатный доступ к готовым Spaces с квотой и очередью.\n\nПеред активацией запиши три вещи: что получаешь, дату первого списания и путь отмены. Проверена официальная страница; доступность твоему аккаунту проверяется отдельно.\n\n#ТолькоВКанале #РадарВыгод"},{"key":"result-cost","text":"🧮 <b>Дешёвый запрос может дать дорогой ролик</b>\n\nСравнивай две связки по одному и тому же принятому результату. Цена одной генерации скрывает брак и ручные исправления.\n\nСкопируй шапку таблицы:\n\n<pre>Связка | Задача | Дата тарифов | Попыток | Принято | Расход сервиса | Минут правок | Минут ожидания | Что не удалось</pre>\n\nФормула для сравнения: <b>все расходы сервиса ÷ число принятых результатов</b>. Время человека держи отдельной колонкой; если переводишь его в деньги, явно укажи выбранную ставку.\n\nЭксперимент: возьми один короткий сценарий и одинаковые референсы. Зафиксируй критерии <i>до</i> генерации: длительность, узнаваемость героя, читаемость текста и звук. Не меняй их после того, как увидишь любимый вариант.\n\nВывод «A выгоднее B» относится только к этому заданию и твоим условиям — зато его можно проверить.\n\n#ТолькоВКанале #ПрактикаИИ"},{"key":"handoff-capsule","text":"💊 <b>Капсула проекта для следующего чата</b>\n\nДлинная переписка не заменяет короткую карту состояния. Перед сменой чата попроси собрать один файл:\n\n<pre>Создай HANDOFF.md: цель; где итоговые файлы; принятые решения; как запустить; какие проверки реально выполнены; известные проблемы; ближайший шаг. Для «готово» укажи файл или результат проверки. Не включай токены, секреты и личные данные. Если есть два варианта решения, отметь выбранный и причину. Не пересказывай всю переписку.</pre>\n\nОткрой новый чат и дай только этот файл плюс рабочую папку. Первый запрос: «Что ты считаешь готовым и что проверишь прежде, чем продолжить?»\n\nЕсли агент уверенно называет то, чего в папке нет, капсулу нужно уточнить. Хорошая передача проекта проверяется продолжением работы, а не длиной документа.\n\n#ТолькоВКанале #РабочиеПриёмы"}],"date":"2026-10-26","destination":"@OGCRE8R"}$editorial$::jsonb) on conflict(key) do nothing;
